import Foundation

/// Type of log action recommended by the AI Nutrition Coach.
public enum AICoachActionKind: String, Codable, Equatable, Sendable {
    case meal
    case supplement
    case water
}

/// A concrete meal, supplement, or hydration logging action generated by the AI Coach.
public struct AICoachLogAction: Codable, Equatable, Sendable, Identifiable {
    public var id: String
    public var kind: AICoachActionKind
    public var itemId: String?
    public var selectedOptionId: String?
    public var title: String
    public var kcal: Double?
    public var protein: Double?
    public var carbs: Double?
    public var fat: Double?
    public var waterMl: Double?
    public var notes: String?

    public init(
        id: String = UUID().uuidString,
        kind: AICoachActionKind,
        itemId: String? = nil,
        selectedOptionId: String? = nil,
        title: String,
        kcal: Double? = nil,
        protein: Double? = nil,
        carbs: Double? = nil,
        fat: Double? = nil,
        waterMl: Double? = nil,
        notes: String? = nil
    ) {
        self.id = id
        self.kind = kind
        self.itemId = itemId
        self.selectedOptionId = selectedOptionId
        self.title = title
        self.kcal = kcal
        self.protein = protein
        self.carbs = carbs
        self.fat = fat
        self.waterMl = waterMl
        self.notes = notes
    }

    enum CodingKeys: String, CodingKey {
        case id
        case kind
        case itemId
        case selectedOptionId
        case title
        case kcal
        case protein
        case carbs
        case fat
        case waterMl
        case notes
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = (try? container.decodeIfPresent(String.self, forKey: .id)) ?? UUID().uuidString
        self.kind = (try? container.decodeIfPresent(AICoachActionKind.self, forKey: .kind)) ?? .meal
        self.itemId = try container.decodeIfPresent(String.self, forKey: .itemId)
        self.selectedOptionId = try container.decodeIfPresent(String.self, forKey: .selectedOptionId)
        self.title = (try? container.decodeIfPresent(String.self, forKey: .title)) ?? "Καταγραφή"
        self.kcal = try container.decodeIfPresent(Double.self, forKey: .kcal)
        self.protein = try container.decodeIfPresent(Double.self, forKey: .protein)
        self.carbs = try container.decodeIfPresent(Double.self, forKey: .carbs)
        self.fat = try container.decodeIfPresent(Double.self, forKey: .fat)
        self.waterMl = try container.decodeIfPresent(Double.self, forKey: .waterMl)
        self.notes = try container.decodeIfPresent(String.self, forKey: .notes)
    }
}

/// Structured response returned by the AI Coach LLM.
public struct AICoachResponse: Codable, Equatable, Sendable {
    public var replyGreek: String
    public var suggestedActions: [AICoachLogAction]

    public init(
        replyGreek: String,
        suggestedActions: [AICoachLogAction] = []
    ) {
        self.replyGreek = replyGreek
        self.suggestedActions = suggestedActions
    }

    enum CodingKeys: String, CodingKey {
        case replyGreek
        case suggestedActions
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.replyGreek = (try? container.decodeIfPresent(String.self, forKey: .replyGreek)) ?? ""
        self.suggestedActions = (try? container.decodeIfPresent([AICoachLogAction].self, forKey: .suggestedActions)) ?? []
    }
}

/// Persistent chat message in the AI Coach conversation.
public struct AICoachChatMessage: Codable, Equatable, Sendable, Identifiable {
    public var id: UUID
    public var isUser: Bool
    public var text: String
    public var timestamp: Date
    public var suggestedActions: [AICoachLogAction]
    public var appliedActionIds: Set<String>
    public var appliedLogIds: [String: String]
    public var modelUsed: String?

    public init(
        id: UUID = UUID(),
        isUser: Bool,
        text: String,
        timestamp: Date = Date(),
        suggestedActions: [AICoachLogAction] = [],
        appliedActionIds: Set<String> = [],
        appliedLogIds: [String: String] = [:],
        modelUsed: String? = nil
    ) {
        self.id = id
        self.isUser = isUser
        self.text = text
        self.timestamp = timestamp
        self.suggestedActions = suggestedActions
        self.appliedActionIds = appliedActionIds
        self.appliedLogIds = appliedLogIds
        self.modelUsed = modelUsed
    }

    enum CodingKeys: String, CodingKey {
        case id
        case isUser
        case text
        case timestamp
        case suggestedActions
        case appliedActionIds
        case appliedLogIds
        case modelUsed
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = (try? container.decodeIfPresent(UUID.self, forKey: .id)) ?? UUID()
        self.isUser = (try? container.decodeIfPresent(Bool.self, forKey: .isUser)) ?? false
        self.text = (try? container.decodeIfPresent(String.self, forKey: .text)) ?? ""
        self.timestamp = (try? container.decodeIfPresent(Date.self, forKey: .timestamp)) ?? Date()
        self.suggestedActions = (try? container.decodeIfPresent([AICoachLogAction].self, forKey: .suggestedActions)) ?? []
        self.appliedActionIds = (try? container.decodeIfPresent(Set<String>.self, forKey: .appliedActionIds)) ?? []
        self.appliedLogIds = (try? container.decodeIfPresent([String: String].self, forKey: .appliedLogIds)) ?? [:]
        self.modelUsed = try container.decodeIfPresent(String.self, forKey: .modelUsed)
    }
}

/// Snapshot of the athlete's current day state provided as context to the AI Coach.
public struct AICoachDailySnapshot: Equatable, Sendable {
    public var date: Date
    public var weekday: Weekday
    public var selectedTemplateKey: String
    public var resolvedEvents: [ScheduledEvent]
    public var logEntries: [LogEntry]
    public var waterIntakeMl: Double
    public var targetWaterMl: Double
    public var selectedOptionIds: [String: String]

    public init(
        date: Date,
        weekday: Weekday,
        selectedTemplateKey: String,
        resolvedEvents: [ScheduledEvent] = [],
        logEntries: [LogEntry] = [],
        waterIntakeMl: Double,
        targetWaterMl: Double,
        selectedOptionIds: [String: String] = [:]
    ) {
        self.date = date
        self.weekday = weekday
        self.selectedTemplateKey = selectedTemplateKey
        self.resolvedEvents = resolvedEvents
        self.logEntries = logEntries
        self.waterIntakeMl = waterIntakeMl
        self.targetWaterMl = targetWaterMl
        self.selectedOptionIds = selectedOptionIds
    }
}
